package compatibility

import (
	"bytes"
	"encoding/hex"
	"encoding/json"
	"os"
	"path/filepath"
	"testing"

	"github.com/vaultys/vaultysid/go/pkg/vaultysid"
)

// pqIdentityVectors is testdata/pq-identity-vectors.json, generated by
// typescript/test/interops/generate-pq-identity-vectors.ts (rfc/PQ-ENCRYPTION.md §11)
// and checked here through the public API. The exact DHIES v3 output is checked
// in pkg/keymanager, where the deterministic encryption is reachable.
type pqIdentityVectors struct {
	Identities map[string]struct {
		Algorithm string `json:"algorithm"`
		Type      int    `json:"type"`
		Secret    string `json:"secret"`
		EK        string `json:"ek"`
		ID        string `json:"id"`
		DID       string `json:"did"`
	} `json:"identities"`
	PRF []struct {
		Identity       string `json:"identity"`
		Message        string `json:"message"`
		HMAC           string `json:"hmac"`
		SecretHashData string `json:"secretHashData"`
		SecretHash     string `json:"secretHash"`
	} `json:"prf"`
	DHIESV3 []struct {
		Name      string `json:"name"`
		Sender    string `json:"sender"`
		Recipient string `json:"recipient"`
		Plaintext string `json:"plaintext"`
		Out       string `json:"out"`
	} `json:"dhiesV3"`
	Negative struct {
		IDs []struct {
			Name string `json:"name"`
			ID   string `json:"id"`
		} `json:"ids"`
		Secrets []struct {
			Name   string `json:"name"`
			Secret string `json:"secret"`
		} `json:"secrets"`
		DHIES []struct {
			Name       string `json:"name"`
			Sender     string `json:"sender"`
			Recipient  string `json:"recipient"`
			Ciphertext string `json:"ciphertext"`
		} `json:"dhies"`
	} `json:"negative"`
}

func loadPQIdentityVectors(t *testing.T) pqIdentityVectors {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("testdata", "pq-identity-vectors.json"))
	if err != nil {
		t.Fatal(err)
	}
	var v pqIdentityVectors
	if err := json.Unmarshal(raw, &v); err != nil {
		t.Fatalf("invalid vectors JSON: %v", err)
	}
	return v
}

func pqHex(t *testing.T, s string) []byte {
	t.Helper()
	b, err := hex.DecodeString(s)
	if err != nil {
		t.Fatal(err)
	}
	return b
}

// hybridSupported: the Go library does not implement Hybrid
// (dilithium_ed25519) key managers yet; their vectors are skipped.
const hybridSupported = false

// loadPQIdentities restores every vector identity from its secret, checks its
// id, DID and ML-KEM key, and returns them by name.
func loadPQIdentities(t *testing.T, v pqIdentityVectors) map[string]*vaultysid.VaultysID {
	t.Helper()
	ids := map[string]*vaultysid.VaultysID{}
	for name, ident := range v.Identities {
		if ident.Algorithm == "dilithium_ed25519" && !hybridSupported {
			t.Logf("%s: skipped, Hybrid key managers are not implemented in Go", name)
			continue
		}
		id, err := vaultysid.FromSecret(pqHex(t, ident.Secret))
		if err != nil {
			t.Fatalf("%s: FromSecret: %v", name, err)
		}
		if hex.EncodeToString(id.ToBytes()) != ident.ID {
			t.Fatalf("%s: id mismatch", name)
		}
		if id.DID() != ident.DID {
			t.Fatalf("%s: DID mismatch", name)
		}
		if ident.EK != "" && hex.EncodeToString(id.GetKEMPublicKey()) != ident.EK {
			t.Fatalf("%s: ML-KEM key mismatch", name)
		}
		ids[name] = id
	}
	return ids
}

func TestPQIdentityVectors(t *testing.T) {
	v := loadPQIdentityVectors(t)
	ids := loadPQIdentities(t, v)
	if len(ids) != 7 && (hybridSupported || len(ids) != 4) {
		t.Fatalf("unexpected number of identities: %d", len(ids))
	}
	for name, ident := range v.Identities {
		id := ids[name]
		if id == nil {
			continue
		}
		if int(id.Type) != ident.Type || id.IsPostQuantum() != (ident.Type >= 0x10) {
			t.Errorf("%s: type", name)
		}
		parsed, err := vaultysid.FromID(pqHex(t, ident.ID), nil)
		if err != nil {
			t.Fatalf("%s: FromID: %v", name, err)
		}
		if hex.EncodeToString(parsed.ToBytes()) != ident.ID || parsed.DID() != ident.DID || !parsed.IsPublic() {
			t.Errorf("%s: FromID round trip", name)
		}
		// role checks ignore the post-quantum flag
		role := ident.Type & 0x0f
		if id.IsMachine() != (role == 0) || id.IsPerson() != (role == 1) || id.IsOrganization() != (role == 2) || id.IsHardware() {
			t.Errorf("%s: role checks", name)
		}
	}
}

func TestPQPRFVectors(t *testing.T) {
	v := loadPQIdentityVectors(t)
	ids := loadPQIdentities(t, v)
	if len(v.PRF) != 6 {
		t.Fatalf("expected 6 PRF vectors, got %d", len(v.PRF))
	}
	for _, p := range v.PRF {
		id := ids[p.Identity]
		if id == nil {
			continue
		}
		mac, err := id.HMAC(p.Message)
		if err != nil || hex.EncodeToString(mac) != p.HMAC {
			t.Errorf("%s: hmac mismatch (%v)", p.Identity, err)
		}
		hash, err := id.GetSecretHash(pqHex(t, p.SecretHashData))
		if err != nil || hex.EncodeToString(hash) != p.SecretHash {
			t.Errorf("%s: getSecretHash mismatch (%v)", p.Identity, err)
		}
	}
}

func TestPQDHIESV3Vectors(t *testing.T) {
	v := loadPQIdentityVectors(t)
	ids := loadPQIdentities(t, v)
	for _, c := range v.DHIESV3 {
		t.Run(c.Name, func(t *testing.T) {
			recipient, sender := ids[c.Recipient], ids[c.Sender]
			if recipient == nil || sender == nil {
				t.Skip("Hybrid key managers are not implemented in Go")
			}
			plaintext, err := recipient.DHIESDecrypt(pqHex(t, c.Out), sender)
			if err != nil || hex.EncodeToString(plaintext) != c.Plaintext {
				t.Fatalf("cannot decrypt the TypeScript message: %v", err)
			}
			// Go to Go, through public ids only on the sender side
			publicRecipient, err := vaultysid.FromID(recipient.ToBytes(), nil)
			if err != nil {
				t.Fatal(err)
			}
			out, err := sender.DHIESEncrypt(pqHex(t, c.Plaintext), publicRecipient)
			if err != nil {
				t.Fatal(err)
			}
			if out[0] != 0x03 || len(out) != len(c.Out)/2 {
				t.Fatalf("expected a DHIES v3 message of %d bytes", len(c.Out)/2)
			}
			publicSender, _ := vaultysid.FromID(sender.ToBytes(), nil)
			got, err := recipient.DHIESDecrypt(out, publicSender)
			if err != nil || !bytes.Equal(got, pqHex(t, c.Plaintext)) {
				t.Fatalf("Go round trip: %v", err)
			}
		})
	}
}

func TestPQNegativeVectors(t *testing.T) {
	v := loadPQIdentityVectors(t)
	ids := loadPQIdentities(t, v)
	for _, n := range v.Negative.IDs {
		if _, err := vaultysid.FromID(pqHex(t, n.ID), nil); err == nil {
			t.Errorf("id %s accepted", n.Name)
		}
	}
	for _, n := range v.Negative.Secrets {
		if _, err := vaultysid.FromSecret(pqHex(t, n.Secret)); err == nil {
			t.Errorf("secret %s accepted", n.Name)
		}
	}
	for _, n := range v.Negative.DHIES {
		if _, err := ids[n.Recipient].DHIESDecrypt(pqHex(t, n.Ciphertext), ids[n.Sender]); err == nil {
			t.Errorf("message %s accepted", n.Name)
		}
	}
	if len(v.Negative.IDs) == 0 || len(v.Negative.Secrets) == 0 || len(v.Negative.DHIES) == 0 {
		t.Fatal("missing negative vectors")
	}
}
